// Generated by kernel/mind/intent/gen_intent.py from mind/kilo/intent (the body model's
// predictions and the moves checked against it). Do not edit: change the Python (or run
// python -m kilo.intent.moves --write) and re-run the script (kernel/host/test.sh runs it with --check).
#ifndef KILO_MIND_INTENT_INTENT_GEN_H
#define KILO_MIND_INTENT_INTENT_GEN_H
#include "intent/table.h"

namespace kilo {
namespace intent {

// kilo.intent.estimate's constants
constexpr int16_t kStillA16 = 320;      // every rate under this (a16/s): still
constexpr uint64_t kStillUs = 400000;     // ...for this long: settled
constexpr uint64_t kConfirmUs = 300000;   // a new answer holds this long before it is the state
constexpr int16_t kEndA16 = 960;        // |pitch| folded about 90 deg at least this: ON_END
constexpr int16_t kSideA16 = 960;       // |roll| from here: on a side
constexpr int16_t kBackA16 = 1920;      // ...past here: on the back
constexpr uint16_t kMovingModes = 0x0019;  // bit m: the body's mode m is a moving one

constexpr int kRowCount = 3;
// The upright states as the body model predicts them (TELEMETRY's a16) and their tolerance.
extern const Row kRows[kRowCount];

constexpr int kMoveCount = 4;
// The moves planned and checked from the model (mind/kilo/intent/moves/), as tricks.
extern const tricks::Trick kMoves[4];
// What Python computes for each kMoves entry, for the tests (as tricks::TrickCheck).
struct MoveCheck {
  uint16_t crc16;
  uint8_t trick_id;
  uint16_t total_ticks;
};
extern const MoveCheck kMoveCheck[4];

constexpr int kEdgeCount = 11;
extern const Edge kEdges[kEdgeCount];
// The first step from a state (row, State order) to a goal (column: Standing, Sitting, Resting):
// an index into kEdges, -1 for none (already there, moving, or no way).
extern const int8_t kNext[kStates][kGoals];

}  // namespace intent
}  // namespace kilo

#endif
